using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Users.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Users.Queries.GetUserById;public sealed class GetUserByIdQueryHandler(IUserRepository repository):IRequestHandler<GetUserByIdQuery,Result<UserDto>>{public async Task<Result<UserDto>>Handle(GetUserByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<UserDto>(UserErrors.NotFound):Result.Success(UserDto.FromEntity(e));}}
